using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
public sealed class HomeBlock {public string id="",size="Normal";public int column;public bool visible=true;}
internal static class HomeLayout {
 internal static readonly string[] Ids={"today","priorities","projects","links","reminders","notes","modes","google","finance","inbox","habits"};
 internal static List<HomeBlock> Defaults(){return new List<HomeBlock>{new HomeBlock{id="priorities",column=0},new HomeBlock{id="today",column=1},new HomeBlock{id="projects",column=2},new HomeBlock{id="links",column=0},new HomeBlock{id="reminders",column=1},new HomeBlock{id="notes",column=0,visible=false},new HomeBlock{id="modes",column=1,visible=false},new HomeBlock{id="google",column=1,visible=false},new HomeBlock{id="finance",column=1,visible=false},new HomeBlock{id="inbox",column=0,visible=false},new HomeBlock{id="habits",column=1,visible=false}};}
 internal static string Name(string id){return id=="inbox"?"Boîte de réception":id=="habits"?"Mes habitudes":id=="finance"?"Mon budget":id=="google"?"Google Drive & Sheets":id=="modes"?"Mes modes":id=="today"?"Ma journée":id=="priorities"?"Mes priorités":id=="projects"?"Mes projets":id=="links"?"Accès rapides":id=="notes"?"Notes récentes":"Prochaines échéances";}
 internal static void Validate(Settings s){if(s==null)return;if(s.HomeBlocks==null)s.HomeBlocks=Defaults();if(s.HomeBlocks.Count>=3&&s.HomeBlocks[0].id=="today"&&s.HomeBlocks[0].column==2&&s.HomeBlocks[1].id=="priorities"&&s.HomeBlocks[1].column==0&&s.HomeBlocks[2].id=="projects"&&s.HomeBlocks[2].column==1){var first=s.HomeBlocks[0];s.HomeBlocks.RemoveAt(0);s.HomeBlocks.Insert(1,first);first.column=1;s.HomeBlocks[2].column=2;}var seen=new HashSet<string>();s.HomeBlocks=s.HomeBlocks.Where(b=>b!=null&&Ids.Contains(b.id)&&seen.Add(b.id)).ToList();foreach(var b in s.HomeBlocks){if(b.column<0||b.column>2)b.column=0;if(b.size!="Compact"&&b.size!="Normal")b.size="Normal";}foreach(var id in Ids)if(!seen.Contains(id))s.HomeBlocks.Add(new HomeBlock{id=id,visible=id=="today",column=id=="today"?2:0});}
 internal static void Test(string folder){var s=new Store(Path.Combine(folder,"layout"));s.Value.settings.HomeBlocks=new List<HomeBlock>{new HomeBlock{id="notes",column=2,size="Compact"},new HomeBlock{id="notes"},new HomeBlock{id="unknown"}};s.Value.settings.ShowBanner=false;s.Save();s=new Store(Path.Combine(folder,"layout"));var blocks=s.Value.settings.HomeBlocks;if(blocks.Count!=Ids.Length||blocks[0].id!="notes"||blocks[0].column!=2||blocks[0].size!="Compact"||s.Value.settings.ShowBanner)throw new Exception("Accueil : persistance ou normalisation invalide.");s.Value.settings.HomeBlocks=null;s.Save();if(s.Value.settings.HomeBlocks.Count!=Ids.Length)throw new Exception("Migration accueil invalide.");}
}
internal sealed partial class ModernWorkspace {
 void HomeWidgets(StackPanel root){var tools=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,0,0,10)};tools.Children.Add(Btn("Concentration",delegate{Go("Concentration");},false,true));tools.Children.Add(Btn("Organiser l’accueil",delegate{EditHome();},false,true));if(!store.Value.settings.ShowBanner)root.Children.Add(tools);var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.3,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});int[] rows={0,0};foreach(var block in store.Value.settings.HomeBlocks.Where(b=>b.visible)){int col=block.column==2?0:block.column,row=block.column==2?Math.Max(rows[0],rows[1]):rows[col];while(grid.RowDefinitions.Count<=row)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});UIElement body;Action more=null;bool compact=block.size=="Compact";var active=store.Value.tasks.Where(t=>t.status!="done");if(block.id=="inbox"){body=InboxHome(compact);more=delegate{Go("Boîte de réception");};}else if(block.id=="habits"){body=HabitsHome(compact);more=delegate{Go("Habitudes");};}else if(block.id=="finance"){body=BudgetHome(compact);more=delegate{Go("Mon budget");};}else if(block.id=="google"){body=GooglePinButtons(compact);more=delegate{Go("Google Drive");};}else if(block.id=="modes"){body=ModeButtons(compact);more=delegate{Go("Mes modes");};}else if(block.id=="today"){body=HomeTimelineV2(compact);more=delegate{Go("Agenda");};}else if(block.id=="priorities"){body=TaskList(active.OrderBy(t=>t.priority=="Haute"?0:1).ThenBy(t=>String.IsNullOrEmpty(t.due)?"9999":t.due),compact?2:3);more=delegate{Go("Mes tâches");};}else if(block.id=="projects"){body=ProjectList(compact?2:3);more=delegate{Go("Mes projets");};}else if(block.id=="reminders"){body=TaskList(active.Where(t=>!String.IsNullOrEmpty(t.due)).OrderBy(t=>t.due),compact?1:3);more=delegate{Go("Rappels");};}else if(block.id=="notes"){var notes=new StackPanel();foreach(var n in store.Value.pages.Where(n=>!n.trashed).OrderByDescending(n=>n.updated).Take(compact?2:4)){var note=n;var button=Btn(n.title,delegate{ReadNote(note);},false,true);button.HorizontalContentAlignment=HorizontalAlignment.Left;notes.Children.Add(button);}notes.Children.Add(Btn("+  Nouvelle page",delegate{EditNote(null,"");},false,true));body=notes;more=delegate{Go("Mes notes");};}else{var links=new WrapPanel();foreach(var link in store.Value.settings.Links){string url=link.Url;var button=Btn(link.Name,delegate{Open(url);});button.Margin=new Thickness(0,0,8,8);button.Padding=new Thickness(8,9,8,9);if(!compact){button.Width=70;ModernIcon(button,url);}else ModernIcon(button,url,false);links.Children.Add(button);}LocalShortcutButtons(links,compact);body=links;}var card=Card(HomeLayout.Name(block.id),body,more);card.VerticalAlignment=VerticalAlignment.Top;card.Margin=new Thickness(0,0,block.column==0?16:0,16);Grid.SetRow(card,row);Grid.SetColumn(card,col);if(block.column==2){Grid.SetColumnSpan(card,2);rows[0]=rows[1]=row+1;}else rows[col]=row+1;grid.Children.Add(card);}root.Children.Add(grid);if(!store.Value.settings.HomeBlocks.Any(b=>b.visible))root.Children.Add(T("Votre accueil est vide. Choisissez les blocs dans « Organiser l’accueil ».",13,Muted));}
 void EditHome(){StackPanel body,actions;var w=Dialog("Organiser mon accueil",out body,out actions,760);var settings=store.Value.settings;var draft=settings.HomeBlocks.Select(b=>new HomeBlock{id=b.id,column=b.column,size=b.size,visible=b.visible}).ToList();var banner=new CheckBox{Content="Afficher le message d’accueil",IsChecked=settings.ShowBanner,Margin=new Thickness(0,0,0,10)};var stats=new CheckBox{Content="Afficher les compteurs",IsChecked=settings.ShowStats,Margin=new Thickness(0,0,0,20)};body.Children.Add(banner);body.Children.Add(stats);body.Children.Add(T("Choisissez l’ordre, la largeur et le contenu de vos blocs.",12,Muted,new Thickness(0,0,0,16)));var list=new StackPanel();body.Children.Add(list);Action draw=null;draw=delegate{list.Children.Clear();for(int i=0;i<draft.Count;i++){int index=i;var block=draft[i];var panel=new StackPanel();var first=new DockPanel();var arrows=new StackPanel{Orientation=Orientation.Horizontal};arrows.Children.Add(Btn("↑",delegate{if(index>0){draft.RemoveAt(index);draft.Insert(index-1,block);draw();}},false,true));arrows.Children.Add(Btn("↓",delegate{if(index<draft.Count-1){draft.RemoveAt(index);draft.Insert(index+1,block);draw();}},false,true));DockPanel.SetDock(arrows,Dock.Right);first.Children.Add(arrows);var visible=new CheckBox{Content=HomeLayout.Name(block.id),IsChecked=block.visible,VerticalAlignment=VerticalAlignment.Center};visible.Click+=delegate{block.visible=visible.IsChecked==true;};first.Children.Add(visible);panel.Children.Add(first);var options=new WrapPanel{Margin=new Thickness(0,8,0,0)};var column=Combo(new[]{"Colonne gauche","Colonne droite","Toute la largeur"},block.column==0?"Colonne gauche":block.column==1?"Colonne droite":"Toute la largeur");column.Width=235;column.Margin=new Thickness(0,0,10,0);column.SelectionChanged+=delegate{block.column=column.SelectedIndex;};options.Children.Add(column);var size=Combo(new[]{"Normal","Compact"},block.size);size.Width=170;size.SelectionChanged+=delegate{block.size=Convert.ToString(size.SelectedItem);};options.Children.Add(size);panel.Children.Add(options);var card=Box(panel,new Thickness(12));card.Margin=new Thickness(0,0,0,10);list.Children.Add(card);}};draw();actions.Children.Add(Btn("Réinitialiser",delegate{draft=HomeLayout.Defaults();banner.IsChecked=stats.IsChecked=true;draw();},false,true));actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{settings.HomeBlocks=draft;settings.ShowBanner=banner.IsChecked==true;settings.ShowStats=stats.IsChecked==true;if(owner.Save())w.DialogResult=true;},true));ShowWindow(w);Refresh();}
}
